#include <bits/stdc++.h>

using namespace std;
using ll = long long;

const int MOD = 998244353;

inline int add(int a, int b) {
    a += b;
    return a - MOD * (a >= MOD);
}

inline int mult(int a, int b) {
    return (ll)a * b % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<int> a(n);
    for (int &x : a) {
        cin >> x;
    }

    for (int i = 0; i < n; ++i) {
        a.push_back(a[i]);
    }
    a.insert(a.begin(), 0);

    vector<int> prev(2 * n + 1), cur(2 * n + 1);
    prev[n] = 1;

    for (int i = 1; i <= n; ++i) {
        fill(cur.begin(), cur.end(), 0);
        bool different = a[i] != a[i + 1];

        for (int j = 0; j <= 2 * n; ++j) {
            if (different) {
                if (j > 0) {
                    cur[j] = add(cur[j], prev[j - 1]);
                }
                if (j < 2 * n) {
                    cur[j] = add(cur[j], prev[j + 1]);
                }
            }

            cur[j] = add(cur[j], mult(prev[j], max(0, k - 2 * different)));
        }

        swap(prev, cur);
    }

    int ans = 0;
    for (int i = n + 1; i <= 2 * n; ++i) {
        ans = add(ans, prev[i]);
    }

    cout << ans << '\n';
    return 0;
}

