using namespace std;
using ll = long long;

const int MOD = 998244353;

inline int add(int a, int b) {
    a += b;
    return a >= MOD ? a - MOD : a;
}

inline int mult(int a, int b) {
    return static_cast<ll>(a) * b % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

