    prev[n] = 1;

    for (int i = 0; i < n; ++i) {
        fill(cur.begin(), cur.end(), 0);

        bool different = a[i] != a[(i + 1) % n];
        int sameWays = max(0, k - 2 * static_cast<int>(different));

        for (int j = 0; j <= 2 * n; ++j) {
            cur[j] = mult(prev[j], sameWays);

            if (different) {
                if (j > 0) {
                    cur[j] = add(cur[j], prev[j - 1]);
                }
                if (j < 2 * n) {
                    cur[j] = add(cur[j], prev[j + 1]);
                }
            }
        }

        prev.swap(cur);
    }

    int ans = 0;
    for (int i = n + 1; i <= 2 * n; ++i) {
        ans = add(ans, prev[i]);
    }

    cout << ans << '\n';
    return 0;
